SELECT cc.symbol, i.interval_code, s.last_signal_ksa, TIMESTAMPDIFF(MINUTE, s.last_signal_ksa, NOW()) AS signal_minutes_stale, c.last_candle_close_ksa, TIMESTAMPDIFF(MINUTE, c.last_candle_close_ksa, NOW()) AS candle_minutes_stale FROM coin_configuration cc CROSS JOIN (SELECT '1m' interval_code UNION ALL SELECT '5m' UNION ALL SELECT '1h') i LEFT JOIN (SELECT symbol, interval_code, MAX(generated_at) AS last_signal_ksa FROM trade_signal WHERE generated_at >= NOW() - INTERVAL 4 HOUR AND interval_code IN ('1m','5m','1h') GROUP BY symbol, interval_code) s ON s.symbol = cc.symbol AND s.interval_code = i.interval_code LEFT JOIN (SELECT symbol, interval_code, MAX(close_time) AS last_candle_close_ksa FROM candle WHERE closed = 1 AND close_time >= NOW() - INTERVAL 4 HOUR AND interval_code IN ('1m','5m','1h') GROUP BY symbol, interval_code) c ON c.symbol = cc.symbol AND c.interval_code = i.interval_code WHERE cc.enabled = 1 ORDER BY signal_minutes_stale DESC, candle_minutes_stale DESC, cc.symbol, i.interval_code